// Mesma lista/ids do array OBRAS em prototipo/index.html -- mesmo motivo
// dos outros 2 fluxos de Suprimentos/OC: essa API exige `obra_id` (ou
// `rmi_id`) por chamada, sem endpoint "lista todas as obras". CNPEM -
// Auditório (id 103) fica DE FORA de propósito, mesma decisão já tomada
// nos outros fluxos. Se uma obra nova entrar no painel, adicionar aqui
// também.
const OBRAS = [
  { id: 106, nome: 'CNPEM - Faseado' },
  { id: 110, nome: 'Hitachi' },
  { id: 94,  nome: 'Porto Itapoá' },
  { id: 107, nome: 'Novo Nordisk - AP' },
  { id: 108, nome: 'Novo Nordisk - AP - Reforço' },
  { id: 91,  nome: 'Novo Nordisk - UB/SP' },
];

return OBRAS.map(o => ({ json: { id_obra: o.id, nome_obra: o.nome } }));

// Modo padrão "Run Once for All Items" (não mexer) -- fan-out de 1 item
// de obra pra N linhas de item de RMI, mesmo padrão dos outros fluxos de
// Suprimentos.
//
// Casa cada resposta HTTP com sua obra de origem por POSIÇÃO. Guard
// explícito: se as contagens não baterem, aborta em vez de arriscar
// juntar item com obra errada.
const listaObras = $('Lista de obras').all();
const respostas = $input.all();
if (listaObras.length !== respostas.length) {
  throw new Error(`Descompasso entre lista de obras (${listaObras.length}) e respostas HTTP (${respostas.length}) -- abortando pra não misturar item com obra errada.`);
}

const num = (v) => (v === null || v === undefined || v === '') ? null : Number(v);
const bool = (v) => v === true || v === 'true' || v === 1;

return respostas.map((resp, i) => {
  const idObra = listaObras[i].json.id_obra;
  const corpo = resp.json;
  const itens = Array.isArray(corpo?.data) ? corpo.data : [];

  // Guard de paginação -- essa API (diferente da de Mapa de Compras)
  // CONFIRMA um campo `total` no envelope da resposta. Com `all=true` o
  // esperado é vir tudo numa resposta só; se `total` não bater com quantos
  // itens vieram em `data`, `all=true` não desligou a paginação como
  // esperado e falta implementar loop de `page` pra essa obra -- melhor
  // travar aqui do que gravar só uma fatia dos itens sem avisar.
  if (typeof corpo?.total === 'number' && corpo.total !== itens.length) {
    throw new Error(`Obra ${idObra}: API reportou total=${corpo.total} mas 'data' trouxe ${itens.length} itens -- all=true não trouxe tudo de uma vez, precisa de paginação manual (page=1,2,3...) pra essa obra.`);
  }

  const linhas = itens.map(it => ({
    id: num(it.id),
    id_rmi: num(it.id_rmi),
    nome_rmi: it.nome_rmi || null,
    id_obra: idObra,
    obra_nome: it.obra || null,
    codigo_seq: it.codigo_seq != null ? String(it.codigo_seq) : null,
    nivel: num(it.nivel),
    eh_item_pai: bool(it.eh_item_pai),
    codigo_lam: it.codigo_lam || null,
    codigo_s1: it.codigo_s1 || null,
    descricao: it.descricao || null,
    unidade: it.unidade || null,
    quantidade: num(it.quantidade),
    quantidade_consumida: num(it.quantidade_consumida),
    data_necessidade_compra: it.data_necessidade_compra || null,
    preco_referencia_bd_s1: num(it.preco_referencia_bd_s1),
    subtotal_referencia_bd_s1: num(it.subtotal_referencia_bd_s1),
    custo_meta_orcamento: num(it.custo_meta_orcamento),
    subtotal_custo_meta_orcamento: num(it.subtotal_custo_meta_orcamento),
    total_consumido: num(it.total_consumido),
    total_consumido_proprio: num(it.total_consumido_proprio),
    saldo_orcamentario: num(it.saldo_orcamentario),
    desvio_saldo_orcamentario: it.desvio_saldo_orcamentario || null,
    desvio_cor: it.desvio_cor || null,
    prazo_status: it.prazo_status || null,
    prazo_cor: it.prazo_cor || null,
    raw: it,
    atualizado_em: new Date().toISOString(),
  }));
  return { json: { id_obra: idObra, linhas } };
});
